package com.yonlab.vision;
import android.app.Activity;import android.content.Context;import android.graphics.Bitmap;import android.os.*;import android.view.TextureView;import org.json.*;import java.lang.ref.WeakReference;import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Foreground-only actual audience estimation, one in-flight frame and at most one start per second. */
final class SignageAudience implements CameraPipe.Sink {
 interface Listener {void audienceObserved(SignageAudience owner,AudiencePolicy.Summary summary);void audienceFailed(SignageAudience owner);}
 private static final AtomicLong IDS=new AtomicLong(SystemClock.elapsedRealtimeNanos()),LATEST=new AtomicLong();private static final AtomicReference<SignageAudience> PENDING=new AtomicReference<>();private static final AtomicBoolean DRAINING=new AtomicBoolean();private static final ThreadPoolExecutor REPORTER=new ThreadPoolExecutor(0,1,1,TimeUnit.SECONDS,new ArrayBlockingQueue<>(1),r->{Thread t=new Thread(r,"YOnAudienceRecord");t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());
 final long id=IDS.incrementAndGet();private final Context app;private final WeakReference<Listener> listener;private final Handler main=new Handler(Looper.getMainLooper());private final AtomicBoolean started=new AtomicBoolean(),canceled=new AtomicBoolean(),busy=new AtomicBoolean(),eventWritten=new AtomicBoolean();private final ThreadPoolExecutor worker;private volatile CameraPipe camera;private FaceEngine engine;private String modelId="";
 private volatile boolean ready,previewReady,cameraClosed,workerClosed,engineCloseReturned;private volatile long nextAt,frames,previewFrames,analysisMs;private volatile int width,height;private volatile String phase="STARTING",reason="",error="",cleanupError="";private volatile AudiencePolicy.Summary summary=AudiencePolicy.select(Collections.emptyList());
 SignageAudience(Activity owner,TextureView view,Listener target){app=owner.getApplicationContext();listener=new WeakReference<>(target);worker=new ThreadPoolExecutor(0,1,1,TimeUnit.SECONDS,new ArrayBlockingQueue<>(2),r->{Thread t=new Thread(r,"YOnAudience-"+id);t.setDaemon(true);return t;},new ThreadPoolExecutor.AbortPolicy());camera=new CameraPipe(owner,view,null,this,null,640,false);camera.afterStopped(()->{cameraClosed=true;camera=null;report();});}
 void start(){if(!started.compareAndSet(false,true))return;LATEST.set(id);report();worker.execute(()->{try{if(canceled.get())return;String selected=OneModels.selected(app,"signage");modelId="android-media".equals(selected)?OneModels.selected(app,"vis"):selected;engine=new FaceEngine(app,"vis",modelId);ready=!canceled.get();}catch(Exception|LinkageError|OutOfMemoryError e){fail(e);}});CameraPipe p=camera;if(p!=null)p.start();}
 public boolean acceptsFrames(){return ready&&previewReady&&!canceled.get()&&!busy.get()&&SystemClock.elapsedRealtime()>=nextAt;}
 public void frame(BgrFrame frame){if(canceled.get()||!ready||!busy.compareAndSet(false,true)){frame.close();return;}nextAt=SystemClock.elapsedRealtime()+1000;try{worker.execute(()->analyze(frame));}catch(RejectedExecutionException e){busy.set(false);frame.close();}}
 private void analyze(BgrFrame frame){Bitmap bitmap=null;long start=SystemClock.elapsedRealtime();try{if(canceled.get())return;int[] pixels=new int[frame.width*frame.height];for(int i=0,j=0;i<pixels.length;i++,j+=3)pixels[i]=0xff000000|((frame.data[j+2]&255)<<16)|((frame.data[j+1]&255)<<8)|(frame.data[j]&255);bitmap=Bitmap.createBitmap(pixels,frame.width,frame.height,Bitmap.Config.ARGB_8888);List<Observations.Face> observed=engine.analyze(bitmap,false,true);if(canceled.get())return;AudiencePolicy.Summary current=AudiencePolicy.select(observed);summary=current;width=frame.width;height=frame.height;frames++;analysisMs=SystemClock.elapsedRealtime()-start;phase="RUNNING";report();main.post(()->{Listener l=listener.get();if(l!=null&&!canceled.get())l.audienceObserved(this,current);});}catch(Exception|LinkageError|OutOfMemoryError e){fail(e);}finally{if(bitmap!=null&&!bitmap.isRecycled())bitmap.recycle();frame.close();busy.set(false);}}
 public void status(String text){}
 public void failed(String text){fail(new IllegalStateException("camera"));}
 public void previewReady(int w,int h,boolean mirrored){width=w;height=h;previewReady=true;}
 void updateTransform(){CameraPipe p=camera;if(p!=null)p.updateTransform();}
 void previewFrame(){previewFrames++;}
 private void fail(Throwable failure){if(canceled.get())return;error=failure.getClass().getSimpleName();stop("ERROR");main.post(()->{Listener l=listener.get();if(l!=null)l.audienceFailed(this);});}
 void stop(String why){if(!canceled.compareAndSet(false,true))return;ready=false;phase="CLOSING";reason=why;CameraPipe p=camera;if(p!=null)p.stop();else cameraClosed=true;try{worker.execute(()->{try{if(engine!=null)engine.close();engineCloseReturned=true;}catch(Exception|LinkageError e){cleanupError=e.getClass().getSimpleName();}finally{engine=null;workerClosed=true;report();}});worker.shutdown();}catch(RejectedExecutionException e){cleanupError=e.getClass().getSimpleName();worker.shutdown();}report();}
 private void report(){if(LATEST.get()!=id)return;for(;;){SignageAudience old=PENDING.get();if(old!=null&&old.id>id)return;if(PENDING.compareAndSet(old,this))break;}drainLater();}
 private static void drainLater(){if(!DRAINING.compareAndSet(false,true))return;try{REPORTER.execute(()->{try{for(;;){SignageAudience value=PENDING.getAndSet(null);if(value!=null)value.write();if(PENDING.get()==null)break;}}finally{DRAINING.set(false);if(PENDING.get()!=null)drainLater();}});}catch(RejectedExecutionException e){DRAINING.set(false);android.util.Log.e("YOn","audience_record_queue",e);}}
 private void write(){if(LATEST.get()!=id)return;try{AudiencePolicy.Summary s=summary;JSONArray bins=new JSONArray();for(int n:s.groups)bins.put(n);boolean closed=cameraClosed&&workerClosed;JSONObject value=new JSONObject().put("sessionId",id).put("modelId",modelId).put("state",closed?"CLOSED":phase).put("reason",reason).put("errorType",error).put("cleanupErrorType",cleanupError).put("frames",frames).put("previewFrames",previewFrames).put("width",width).put("height",height).put("analysisMs",analysisMs).put("intervalMs",1000).put("faceCount",s.faceCount).put("knownAgeCount",s.knownAges).put("ageGroups",bins).put("selectedGroup",s.group).put("cameraClosed",cameraClosed).put("workerClear",workerClosed).put("ownerClosed",closed).put("engineCloseReturned",engineCloseReturned).put("ageModelSha256",FaceEngine.AGE_GENDER_SHA256).put("elapsedMs",SystemClock.elapsedRealtime());Records.write(app,"signage-audience.json",value);if(closed&&eventWritten.compareAndSet(false,true))Records.event(app,"signage-audience","CLOSED",new JSONObject().put("sessionId",id).put("modelId",modelId).put("frames",frames).put("reason",reason).put("faceCount",s.faceCount).put("knownAgeCount",s.knownAges));}catch(JSONException ignored){}}
}
